static void tb_0374_item_take_aa_glock() {
  EkTakeState s = tb374_state();
  s.ammo[1] = 200; CHECK_MSG(ekm_item_refused(8176, 0, s), "Duke, bit 8, pistol full: refused");
  s.ammo[1] = 199; CHECK_MSG(!ekm_item_refused(8176, 0, s), "one below: taken");
  s.ammo[1] = 200; s.gotWeapon &= ~2;
  CHECK_MSG(!ekm_item_refused(8176, 0, s), "no pistol: the Glock gives it");
  s = tb374_state(); s.ammo[1] = 200; s.var[EKM_TV_UP_DUKE_PISTOL] = 4;
  CHECK_MSG(!ekm_item_refused(8176, 0, s), "bit 8 clear: shown");
  s.pchar = 1; CHECK_MSG(ekm_item_refused(8176, 0, s), "Bombshell reads her own array");
  s.var[EKM_TV_UP_SHELLY_PISTOL] = 0; CHECK(!ekm_item_refused(8176, 0, s));
  for (int pc = 2; pc <= 4; pc++) {
    s = tb374_state(); s.ammo[1] = 200; s.pchar = pc;
    CHECK_MSG(!ekm_item_refused(8176, 0, s), "pchar 2/3/4: a stale B, shown");
  }
  // LASERMODE > 0: the pistolammo pool alone (:1954-1961), ammo[1] is not read.
  s = tb374_state(); s.var[EKM_TV_LASERMODE] = 1; s.var[EKM_TV_PISTOLAMMO] = 200;
  CHECK_MSG(ekm_item_refused(8176, 0, s), "laser mode, pistolammo full: refused");
  s.ammo[1] = 200; s.var[EKM_TV_PISTOLAMMO] = 199;
  CHECK_MSG(!ekm_item_refused(8176, 0, s), "laser mode, one below: taken");
  s.var[EKM_TV_PISTOLAMMO] = 200; s.gotVar[EKM_TV_PISTOLAMMO] = false;
  CHECK_MSG(!ekm_item_refused(8176, 0, s), "pistolammo unread: shown");
  // Every input read is needed: each unread one shows the sprite.
  s = tb374_state(); s.ammo[1] = 200; s.gotVar[EKM_TV_LASERMODE] = false;
  CHECK_MSG(!ekm_item_refused(8176, 0, s), "LASERMODE unread: shown");
  s = tb374_state(); s.ammo[1] = 200; s.gotVar[EKM_TV_UP_DUKE_PISTOL] = false;
  CHECK_MSG(!ekm_item_refused(8176, 0, s), "Duke's upgrade element unread: shown");
  s = tb374_state(); s.ammo[1] = 200; s.pchar = 1; s.gotVar[EKM_TV_UP_SHELLY_PISTOL] = false;
  CHECK_MSG(!ekm_item_refused(8176, 0, s), "Bombshell's upgrade element unread: shown");
  s = tb374_state(); s.ammo[1] = 200; s.gotPchar = false;
  CHECK_MSG(!ekm_item_refused(8176, 0, s), "pchar unread: shown");
  s = tb374_state(); s.ammo[1] = 200; s.gotPs = false;
  CHECK_MSG(!ekm_item_refused(8176, 0, s), "struct unread: shown");
  const unsigned long long m = ekm_take_var_mask(8176);
  CHECK_MSG(m == ((1ull << EKM_TV_LASERMODE) | (1ull << EKM_TV_PISTOLAMMO) |
                  (1ull << EKM_TV_UP_DUKE_PISTOL) | (1ull << EKM_TV_UP_SHELLY_PISTOL)),
            "mask names exactly the four Glock vars");
  CHECK(ekm_item_take_category(8176) == EKM_TAKE_CAT_WEAPON);
}

static EkmSpinIn tb375_minigun() {
  EkmSpinIn s = {};
  s.weaponOk = true; s.weapon = EK_WEAPON_CHAINGUN; s.ammoOk = true; s.ammo = 0;
  s.pcharOk = true; s.pchar = 0; s.dukeUpOk = true; s.dukeUp = 1;
  s.gotshockOk = true; s.gotshock = 0; s.railOk = true; s.gotrailgun = 0;
  return s;
}

static void tb_0375_tbot_empty_spin() {
  EkmSpinIn s = tb375_minigun();
  CHECK_MSG(ekm_tbot_empty_spin(s), "minigun Duke at 0: hold");
  s.ammo = 1; CHECK_MSG(!ekm_tbot_empty_spin(s), "at 1: fire");
  s = tb375_minigun(); s.dukeUp = 0; CHECK_MSG(!ekm_tbot_empty_spin(s), "no minigun: fire");
  s.dukeUp = 8 | 4; CHECK_MSG(!ekm_tbot_empty_spin(s), "other bits only: fire");
  s = tb375_minigun(); s.dukeUp = 1 | 8; s.gotshock = 2 | 1;
  CHECK_MSG(!ekm_tbot_empty_spin(s), "the Executioner on top: the shock branch, fire");
  s.gotshock = 1; CHECK_MSG(ekm_tbot_empty_spin(s), "owns it, chaingun on top: hold");
  s.gotshockOk = false; CHECK_MSG(!ekm_tbot_empty_spin(s), "bit 8 set and gotshock unread: fire");
  s = tb375_minigun(); s.gotshockOk = false;
  CHECK_MSG(ekm_tbot_empty_spin(s), "no bit 8: gotshock is not an input");
  for (int pc = 1; pc <= 3; pc++) {
    s = tb375_minigun(); s.pchar = pc;
    CHECK_MSG(!ekm_tbot_empty_spin(s), "Bombshell, Wes, Mando: no spin-up chaingun");
  }
  s = tb375_minigun(); s.pchar = 4; s.dukeUp = 0;
  CHECK_MSG(ekm_tbot_empty_spin(s), "Dea Nova's chaingun spins without an upgrade");
  s.ammo = 1; CHECK_MSG(!ekm_tbot_empty_spin(s), "Dea Nova at 1: fire");
  s = tb375_minigun(); s.pchar = 4; s.dukeUp = 8; s.gotshock = 2;
  CHECK_MSG(!ekm_tbot_empty_spin(s), "Dea Nova, Executioner on top: fire");
  s = tb375_minigun(); s.weapon = EK_WEAPON_DEVISTATOR; s.pchar = 3; s.dukeUpOk = false;
  CHECK_MSG(ekm_tbot_empty_spin(s), "Mando's Devastator at 0: hold");
  s.pchar = 4; CHECK_MSG(ekm_tbot_empty_spin(s), "Dea Nova's Devastator at 0: hold");
  s.gotrailgun = 2; CHECK_MSG(!ekm_tbot_empty_spin(s), "the railgun on top: fire");
  s.gotrailgun = 0; s.railOk = false; CHECK_MSG(!ekm_tbot_empty_spin(s), "gotrailgun unread: fire");
  s.railOk = true; s.ammo = 1; CHECK_MSG(!ekm_tbot_empty_spin(s), "Devastator at 1: fire");
  s.ammo = 0; s.pchar = 0; CHECK_MSG(!ekm_tbot_empty_spin(s), "Duke's Devastator: fire");
  s = tb375_minigun(); s.weapon = EK_WEAPON_SHOTGUN; CHECK(!ekm_tbot_empty_spin(s));
  s = tb375_minigun(); s.weaponOk = false; CHECK_MSG(!ekm_tbot_empty_spin(s), "weapon unread: fire");
  s = tb375_minigun(); s.ammoOk = false; CHECK_MSG(!ekm_tbot_empty_spin(s), "ammo unread: fire");
  s = tb375_minigun(); s.pcharOk = false; CHECK_MSG(!ekm_tbot_empty_spin(s), "pchar unread: fire");
  s = tb375_minigun(); s.dukeUpOk = false; CHECK_MSG(!ekm_tbot_empty_spin(s), "upgrades unread: fire");
}

static void tb_0369_sidegun() {
  CHECK(ekm_picnum_is_attachment(16510));
  CHECK(!ekm_picnum_is_attachment(16509) && !ekm_picnum_is_attachment(16560));
  CHECK(ekm_target_picnum_refusal(16510, true, true, false, true, 0) == EKM_REFUSE_ATTACHMENT);
  CHECK_MSG(ekm_target_picnum_refusal(16510, true, true, false, false, 0) == EKM_REFUSE_ATTACHMENT,
            "the cheap call already names it");
  CHECK_MSG(ekm_target_picnum_refusal(16510, false, false, false, false, 0) == EKM_REFUSE_ATTACHMENT,
            "needs no badguy table");
  CHECK_MSG(ekm_target_picnum_refusal(16510, true, true, false, true, 1) == EKM_REFUSE_FRIENDLY,
            "the player's own sidegun is still a friendly");
  CHECK_MSG(ekm_target_picnum_refusal(1680, true, true, false, true, 0) == EKM_REFUSE_NONE,
            "its host is not refused");
  CHECK_MSG(ekm_target_refusal_awaits_team(EKM_REFUSE_ATTACHMENT) &&
                ekm_target_refusal_awaits_team(EKM_REFUSE_NONE),
            "the team read still runs where FRIENDLY could outrank");
  CHECK(!ekm_target_refusal_awaits_team(EKM_REFUSE_NOTENEMY) &&
        !ekm_target_refusal_awaits_team(EKM_REFUSE_CRITTER) &&
        !ekm_target_refusal_awaits_team(EKM_REFUSE_FRIENDLY));
  CHECK_MSG(ekm_target_refusal_hostile_listed(EKM_REFUSE_ATTACHMENT) &&
                ekm_target_refusal_hostile_listed(EKM_REFUSE_NONE),
            "the ESP's hostile list keeps a sidegun");
  CHECK(!ekm_target_refusal_hostile_listed(EKM_REFUSE_FRIENDLY) &&
        !ekm_target_refusal_hostile_listed(EKM_REFUSE_NOTENEMY));

  CHECK(ekm_ray_attachment(TBOT_RAY_BLOCKED, 12, true, true) == TBOT_RAY_ATTACHMENT);
  CHECK_MSG(ekm_ray_attachment(TBOT_RAY_BLOCKED, 12, false, true) == TBOT_RAY_BLOCKED,
            "an unread record blocks as today");
  CHECK(ekm_ray_attachment(TBOT_RAY_BLOCKED, 12, true, false) == TBOT_RAY_BLOCKED);
  CHECK(ekm_ray_attachment(TBOT_RAY_BLOCKED, -1, true, true) == TBOT_RAY_BLOCKED);
  CHECK_MSG(ekm_ray_attachment(TBOT_RAY_ENEMY, 12, true, true) == TBOT_RAY_ENEMY,
            "only a BLOCKED ray is ever refined");
  CHECK(!ekm_ray_reachable(TBOT_RAY_ATTACHMENT));
  const TbotCond on = { 1, "lock" };
  const TbotCond c = tbot_ray_cond(on, TBOT_RAY_ATTACHMENT);
  CHECK_MSG(!c.holds && strcmp(c.reason, "sidegun") == 0,
            "a sidegun ray never fires, not even as a last resort");
}

static int census_listed_sum(const char* s) {
  int sum = 0;
  for (const char* p = s; *p; p++) {
    if (*p == 'x' && p > s && p[-1] >= '0' && p[-1] <= '9') sum += atoi(p + 1);
    if (strncmp(p, " and ", 5) == 0) sum += atoi(p + 5);
  }
  return sum;
}

static void tb_0370_census() {
  CHECK(ekm_enemy_like(2000, true));
  CHECK_MSG(!ekm_enemy_like(1234, false), "a prop is not enemy-like");
  CHECK_MSG(ekm_enemy_like(EK_AA_SSLIME, false) && ekm_enemy_like(EK_AA_ROLLYTURRET, false),
            "AA's admitted notenemy actors are enemy-like without a flag");
  CHECK(ekm_enemy_like(EK_AA_PODHEAD, false) && ekm_enemy_like(EK_AA_PODTAIL, false));
  CHECK_MSG(!ekm_enemy_like(EK_AA_PODBODY, false), "the worm body is never admitted");

  // The slot rule: a prop never takes a slot; enemies fill 31, then share one.
  short pics[32] = {};
  int used = 0;
  CHECK(ekm_refusal_slot(pics, &used, 32, 1234, false) == -1 && used == 0);
  int own = 0, overflow = 0;
  for (int k = 0; k < 40; k++) {
    const int s = ekm_refusal_slot(pics, &used, 32, 3000 + k, true);
    if (s == k && k < 31) own++;
    if (s == 31 && k >= 31) overflow++;
  }
  CHECK(own == 31 && overflow == 9 && used == 31);
  CHECK_MSG(ekm_refusal_slot(pics, &used, 32, 3005, true) == 5, "a seen picnum keeps its slot");
  CHECK_MSG(ekm_refusal_slot(pics, &used, 32, 1234, false) == -1, "full or not, a prop gets none");

  // aim.cpp's candidate order: hittable, sidegun, asleep, monstatus, state.
  CHECK(ekm_census_hostile_reason(true, false, false, true, true) == EKM_CEN_AIMABLE);
  CHECK(ekm_census_hostile_reason(false, true, true, false, false) == EKM_CEN_UNHITTABLE);
  CHECK(ekm_census_hostile_reason(true, true, true, false, false) == EKM_CEN_SIDEGUN);
  CHECK(ekm_census_hostile_reason(true, false, true, false, false) == EKM_CEN_ASLEEP);
  CHECK(ekm_census_hostile_reason(true, false, false, false, false) == EKM_CEN_MONSTATUS);
  CHECK(ekm_census_hostile_reason(true, false, false, true, false) == EKM_CEN_STATE);

  // A small census prints every entry and its example, and no "more".
  static EkmCensus c;
  ekm_census_clear(&c);
  for (int k = 0; k < 3; k++) ekm_census_add(&c, EKM_CEN_DOWN, 17036, 1, 0, 0);
  ekm_census_add(&c, EKM_CEN_STATNUM, 2000, 973, 50, 0);
  ekm_census_add(&c, EKM_CEN_STATNUM, 2000, 991, 50, 0);
  ekm_census_add(&c, EKM_CEN_AIMABLE, 2000, 1, 50, 0);
  CHECK_MSG(c.n == 4 && c.total[EKM_CEN_STATNUM] == 2, "statnum keys by the actual value");
  char line[1024];
  const int len = ekm_census_format(c, "plain", line, (int)sizeof(line));
  CHECK(len == (int)strlen(line));
  CHECK(strstr(line, "enemy-like 6 = aimable 1 + listed-not-aimed 0 + friendly 0 + unlisted 5") != NULL);
  CHECK(strstr(line, "down 3: 17036x3 (extra 0 pal 0)") != NULL);
  CHECK(strstr(line, "2000x1 (st 973)") != NULL && strstr(line, "2000x1 (st 991)") != NULL);
  CHECK(strstr(line, " more") == NULL && census_listed_sum(line) == 6);

  // Change detection ignores the example, not the counts.
  static EkmCensus d;
  d = c;
  CHECK(ekm_census_same(c, d));
  d.e[0].exA = 99;
  CHECK_MSG(ekm_census_same(c, d), "an example's health is not a change");
  ekm_census_add(&d, EKM_CEN_DOWN, 17036, 1, 0, 0);
  CHECK(!ekm_census_same(c, d));

  // A full table and a long line: the capped line still adds up to its total.
  ekm_census_clear(&c);
  ekm_census_add(&c, EKM_CEN_FRIENDLY, 30001, 1, 0, 0);
  for (int k = 0; k < 64; k++) {
    ekm_census_add(&c, EKM_CEN_DOWN, 10000 + k, 1, -5, 0);
    ekm_census_add(&c, EKM_CEN_DOWN, 10000 + k, 1, -5, 0);
  }
  for (int k = 0; k < 64; k++) ekm_census_add(&c, EKM_CEN_STATNUM, 20000 + k, 973, 0, 0);
  ekm_census_add(&c, EKM_CEN_ZEROREP, 30000, 1, 0, 0);   // table full: total only
  CHECK(c.n == EKM_CENSUS_ENTRIES && c.total[EKM_CEN_ZEROREP] == 1 &&
        c.total[EKM_CEN_STATNUM] == 64);
  const int len2 = ekm_census_format(c, "split", line, (int)sizeof(line));
  CHECK_MSG(len2 < EKM_CENSUS_LINE_MAX && len2 == (int)strlen(line), "the line stays under 900");
  CHECK(strstr(line, "enemy-like 194 =") != NULL);
  CHECK_MSG(census_listed_sum(line) == 194, "enumerated counts plus the \"more\" equal the total");
  CHECK(strstr(line, "zerorep 1: and 1 more") != NULL);
  CHECK(strstr(line, "friendly 1: 30001x1") != NULL);
}

static void tb_0371_nearest_kept() {
  CHECK(ekm_target_dist2(3, -4) == 25);
  CHECK_MSG(ekm_target_dist2(200000, 200000) == 80000000000LL, "no 32-bit overflow");

  // Four candidates into a cap of three.
  long long d[3] = {};
  int n = 0;
  const long long cand[3] = { 50, 90, 70 };
  for (int k = 0; k < 3; k++) {
    const int s = ekm_target_insert_slot(d, n, 3, -1, cand[k]);
    CHECK_MSG(s == k, "room left: appended");
    d[s] = cand[k];
    n++;
  }
  int far = ekm_target_farthest(d, n);
  CHECK(far == 1);
  CHECK_MSG(ekm_target_insert_slot(d, n, 3, far, 30) == 1, "nearer replaces the farthest");
  CHECK_MSG(ekm_target_insert_slot(d, n, 3, far, 95) == -1, "farther is dropped");
  CHECK_MSG(ekm_target_insert_slot(d, n, 3, far, 90) == -1, "a tie keeps the incumbent");
  d[1] = 30;
  far = ekm_target_farthest(d, n);
  CHECK_MSG(far == 2, "the rescan after a replacement finds the new farthest");
  const long long tie[3] = { 70, 40, 70 };
  CHECK(ekm_target_farthest(tie, 3) == 0 && ekm_target_farthest(tie, 0) == -1);
  CHECK_MSG(ekm_target_insert_slot(d, 0, 0, -1, 1) == -1, "a zero cap takes nothing");

  // The census names the farthest kept distance, and a move is not a change.
  static EkmCensus c, e;
  ekm_census_clear(&c);
  ekm_census_add(&c, EKM_CEN_FULL, 2000, 1, 50, 0);
  c.farHostile = 1234;
  c.farFriendly = -1;
  char line[1024];
  ekm_census_format(c, "plain", line, (int)sizeof(line));
  CHECK(strstr(line, "| farthest kept: hostile 1234 friendly none") != NULL);
  CHECK(strstr(line, "full 1: 2000x1") != NULL && census_listed_sum(line) == 1);
  e = c;
  e.farHostile = 99;
  CHECK_MSG(ekm_census_same(c, e), "the player walking is not a census change");
}

// a killed Pig Cop SUV runs `ai AISUVDYING` (VEHICLES.CON:965-969) and drives on at 1 HP.
static void tb_0372_suv_dying() {
  CHECK_MSG(EK_PICNUM_PIGSUV == 6374, "PIGSUV, AADEFS.CON:1050");
  CHECK_MSG(EK_ACT_AI_ID == 20, "AC_AI_ID is t_data[5] (actors.h:104)");
  CHECK(!ekm_ai_id_usable(0));
  CHECK(ekm_ai_id_usable(1));

  // Ids are apScript offsets; 500 is APIGSUVDYING, 492 APIGSUV1, 524 APIGSUVDEAD.
  EkAiRead dying = {};
  dying.aiId = 900;
  dying.actionId = 500;
  dying.aiActionId = 500;
  dying.aiMoveId = 300;
  dying.aiAction.startframe = 0;
  dying.aiAction.numframes = 1;
  dying.aiAction.viewtype = 5;
  dying.aiAction.incval = 1;
  dying.aiAction.delay = 10;
  dying.aiAction.readable = 1;
  dying.aiAction.plausible = 1;
  dying.hvel = 448;
  dying.vvel = 0;
  dying.readable = 1;
  CHECK_MSG(ekm_actor_suv_dying_aa(6374, dying), "AISUVDYING, still in its own action: crashing");

  EkAiRead live = dying;
  live.aiId = 0;
  CHECK_MSG(!ekm_actor_suv_dying_aa(6374, live),
            "a live SUV has run no ai: same action values, same speed, alive");
  EkAiRead apigsuv1 = dying;
  apigsuv1.actionId = 492;
  CHECK_MSG(!ekm_actor_suv_dying_aa(6374, apigsuv1),
            "equal values at another address are not the ai's action");
  EkAiRead wreck = dying;
  wreck.actionId = 524;
  CHECK_MSG(!ekm_actor_suv_dying_aa(6374, wreck), "the wreck keeps the ai, not the action");
  EkAiRead unread = dying;
  unread.readable = 0;
  CHECK_MSG(!ekm_actor_suv_dying_aa(6374, unread), "a failed read is never crashing");
  CHECK_MSG(!ekm_actor_suv_dying_aa(16865, dying), "picnum-scoped");

  CHECK_MSG(ekm_aa_notenemy_dying_record(6374, true, 2) == EKM_DYING_YES,
            "the wreck: monstatus 2 at strength 150 (VEHICLES.CON:659, :680)");
  CHECK(ekm_aa_notenemy_dying_record(6374, true, 1) == EKM_DYING_UNKNOWN);
  CHECK(ekm_aa_notenemy_dying_record(6374, false, 2) == EKM_DYING_UNKNOWN);
  CHECK_MSG(ekm_actor_state(6374, 150, 0, 257, 48, false, EKM_SUFFER_UNKNOWN,
                            ekm_aa_notenemy_dying_record(6374, true, 2)) == EKA_DOWN,
            "and is neither drawn nor shot");
}

static void tb_0376_polypad_growing() {
  const int pics[3] = { 7270, 7275, 7280 };
  for (int k = 0; k < 3; k++) {
    CHECK_MSG(ekm_polypad_growing_aa(pics[k], true, 2, 9), "growing on a body: no ifhitweapon");
    CHECK_MSG(!ekm_polypad_growing_aa(pics[k], true, 2, 32), "full size: ifhitweapon runs");
  }
  CHECK_MSG(!ekm_polypad_growing_aa(7275, true, 0, 9), "not on a body: no break");
  CHECK_MSG(!ekm_polypad_growing_aa(7275, true, 3, 9), "`ife` is exact: 3 is not 2");
  CHECK_MSG(!ekm_polypad_growing_aa(7275, false, 2, 9), "initflags unread: a target");
  CHECK_MSG(!ekm_polypad_growing_aa(7276, true, 2, 9), "picnum-scoped");

  CHECK_MSG(ekm_actor_state(7275, 400, 0, 257, 9, false, EKM_SUFFER_UNKNOWN,
                            EKM_DYING_UNKNOWN, false, false, EKM_WORM_NONE,
                            ekm_polypad_growing_aa(7275, true, 2, 9)) == EKA_GROWING,
            "a growing pad is its own state");
  CHECK_MSG(ekm_actor_state(7275, 400, 0, 257, 32, false, EKM_SUFFER_UNKNOWN,
                            EKM_DYING_UNKNOWN, false, false, EKM_WORM_NONE,
                            ekm_polypad_growing_aa(7275, true, 2, 32)) == EKA_ALIVE,
            "a full-size pad is alive");
  CHECK_MSG(ekm_actor_state(7275, 0, 0, 257, 9, false, EKM_SUFFER_UNKNOWN,
                            EKM_DYING_UNKNOWN, false, false, EKM_WORM_NONE, true) == EKA_DOWN,
            "below the death terms: a corpse is never labelled");
  CHECK_MSG(ekm_actor_state_shown(EKA_GROWING), "drawn");
  CHECK_MSG(!ekm_actor_state_targetable(EKA_GROWING), "neither locked nor fired at");
  CHECK_MSG(!ekm_actor_state_worm_refused(EKA_GROWING), "not a worm-shielded count");
  const char* const l = ekm_actor_state_label(EKA_GROWING);
  CHECK(l && strcmp(l, "Growing") == 0 && strlen(l) < ESP_HEALTH_NUM_BUFSIZE);
}

static void tb_0377_companion_bot() {
  const int pics[8] = { 7470, 7525, 6656, 6681, 19481, 19521, 22016, 22171 };
  for (int k = 0; k < 8; k++) {
    CHECK_MSG(ekm_aa_companion_bot(pics[k], true, 1, true, 0, true, 0),
              "waiting to be recruited: friendly");
    CHECK_MSG(ekm_aa_companion_bot(pics[k], true, 1, true, 1, true, 30), "recruited: friendly");
    CHECK_MSG(!ekm_aa_companion_bot(pics[k], true, 1 | 131072, true, 0, true, 0),
              "a mimic stays hostile");
    CHECK_MSG(!ekm_aa_companion_bot(pics[k], true, 0, true, 0, true, 1),
              "a mimic stripped by the aura stays hostile");
    CHECK_MSG(!ekm_aa_companion_bot(pics[k], false, 0, true, 0, true, 0),
              "monstflags unread: as before D48");
  }
  CHECK_MSG(!ekm_aa_companion_bot(19481, true, 1, true, -1, true, 0),
            "team -1: a leftover killed this tic");
  CHECK_MSG(!ekm_aa_companion_bot(19481, true, 1, false, 0, true, 0), "team unread: hostile");
  CHECK_MSG(!ekm_aa_companion_bot(19481, true, 1, true, 0, false, 0), "monstatus unread: hostile");
  CHECK_MSG(!ekm_aa_companion_bot(14085, true, 1, true, 0, true, 0), "a team-0 Mando is a hostile rival");
  CHECK_MSG(!ekm_aa_companion_bot(1680, true, 1, true, 0, true, 0), "picnum-scoped");

  CHECK_MSG(ekm_target_picnum_refusal(19481, true, true, false, true, 0, true, 1, true, 0) ==
                EKM_REFUSE_FRIENDLY, "the sequence lists a waiting bot as a friendly");
  CHECK_MSG(ekm_target_picnum_refusal(19481, true, true, false, true, 0, true, 131073, true, 0) ==
                EKM_REFUSE_NONE, "the sequence keeps a mimic hostile");
  CHECK_MSG(ekm_target_picnum_refusal(19481, true, true, false, true, 0, true, 0, true, 1) ==
                EKM_REFUSE_NONE, "the sequence keeps a stripped mimic hostile");
  CHECK_MSG(ekm_target_picnum_refusal(19481, true, true, false, true, 0) == EKM_REFUSE_NONE,
            "no monstflags passed: as before D48");
  CHECK_MSG(ekm_target_picnum_refusal(1680, true, true, false, true, 0, true, 1, true, 0) ==
                EKM_REFUSE_NONE, "a non-bot picnum is unaffected");

  // A Mando at initflags >= 32766 is the character-select mannequin (MANDO.CON:2125, :2218-2222); below it, the hostile
  // rival.
  CHECK(ekm_picnum_is_aa_mando(14085) && ekm_picnum_is_aa_mando(14160) &&
        !ekm_picnum_is_aa_mando(19481));
  CHECK_MSG(ekm_aa_mando_mannequin(14085, true, 32766, true, 0), "mannequin: friendly");
  CHECK_MSG(ekm_aa_mando_mannequin(14160, true, 32766, true, 3), "crouch pose too");
  CHECK_MSG(ekm_aa_mando_mannequin(14085, true, 32767, true, 1), "`ifge`: 32767 too");
  CHECK_MSG(!ekm_aa_mando_mannequin(14085, true, 32765, true, 0), "`ifge` is the bound");
  CHECK_MSG(!ekm_aa_mando_mannequin(14085, true, 0, true, 0), "the rival Mando stays hostile");
  CHECK_MSG(!ekm_aa_mando_mannequin(14085, false, 32766, true, 0), "initflags unread: as before D48");
  CHECK_MSG(!ekm_aa_mando_mannequin(14085, true, 32766, true, -1), "team -1, as the bot rule");
  CHECK_MSG(!ekm_aa_mando_mannequin(14085, true, 32766, false, 0), "team unread, as the bot rule");
  CHECK_MSG(!ekm_aa_mando_mannequin(19481, true, 32766, true, 0), "Mando-scoped");
  CHECK_MSG(ekm_target_picnum_refusal(14085, true, true, false, true, 0, false, 0, false, 0,
                                      true, 32766) == EKM_REFUSE_FRIENDLY,
            "the sequence lists the mannequin as a friendly");
  CHECK_MSG(ekm_target_picnum_refusal(14085, true, true, false, true, 0, false, 0, false, 0,
                                      true, 0) == EKM_REFUSE_NONE,
            "the sequence keeps the rival hostile");
  CHECK_MSG(ekm_target_picnum_refusal(14085, true, true, false, true, 0, false, 0, false, 0,
                                      false, 32766) == EKM_REFUSE_NONE,
            "the sequence: unread stays hostile");
}

// tb_0378: -- DEABOT (22016) and its crouch pose (22171) read "Dea bot", the same curated-row + derived-base route
// WESBOT/WESBOTCROUCH use.
static void tb_0378_deabot_name() {
  const char* const s = ekm_enemy_name_derived_aa_string(22016);
  CHECK(s && strcmp(s, "Dea bot") == 0);                       // DEABOT
  CHECK(ekm_enemy_name_derived_aa_base(22171) == 22016);       // DEABOTCROUCH -> DEABOT
  const int base = ekm_enemy_name_derived_aa_base(22171);
  const char* const c = base ? ekm_actor_name_rules_via_derived_base(base, 0, false, 0, false, 0) : 0;
  CHECK_MSG(c && strcmp(c, "Dea bot") == 0, "DEABOTCROUCH p0 reads Dea bot through the chain");
}

// tb_0379: -- "I found an enemy with the name 22819".
static const char* tb_0379_chain(int picnum, int pal) {
  const char* const n = ekm_actor_name_rules(picnum, pal, false, 0, false, 0);
  if (n) return n;
  const char* const s = ekm_enemy_name_derived_aa_string(picnum);
  if (s) return s;
  const int base = ekm_enemy_name_derived_aa_base(picnum);
  return base ? ekm_actor_name_rules_via_derived_base(base, pal, false, 0, false, 0) : 0;
}

static void tb_0379_aa6e_number_tier() {
  struct Row { int picnum; int pal; const char* want; };
  static const Row rows[] = {
    {22819, 0, "Armored Trooper"},   // ARMLIZJETPACK, the reported one
    {22785, 0, "Armored Trooper"},   // ARMLIZSTAYPUT
    {22640, 0, "General Graves"},    // GRAVESNOGUN
    {22700, 0, "Giant Guy"},         // GIANTGUY
    {23706, 0, "Zombie"},            // ZOMBIEHEADSHOT2
    {24198, 0, "Civilian"},          // NIPCHEER
    {24199, 0, "Civilian"},          // NIPCHEERSTAYPUT via base row
    {24243, 0, "Civilian"},          // NIPCHEERCROUCH via base row
    {24350, 0, "Trooper"},           // NIPTROOPJETPACK via base row
    {24350, 21, "Captain"},          // its pal-21 override still applies
    {24455, 0, "Trooper"},           // NIPSABERDEATH
    {25970, 0, "Jikurai"},           // JIKURAI
    {11326, 0, "Seagull"},           // SEAGULL
  };
  for (const Row& r : rows) {
    const char* const got = tb_0379_chain(r.picnum, r.pal);
    CHECK_MSG(got && strcmp(got, r.want) == 0, "AA6e: a formerly bare-number picnum reads its name");
  }
  CHECK_MSG(tb_0379_chain(1638, 0) == 0, "AA6e: SEAGULLSHIT stays unnamed (no evidence)");
}

